//! 🏛️ Writes explicitly owned model placements, geometry references, property sets and relations.
use crate::standards::v1::subsets::base::schema::geometry::{SemioTransform,SemioPoint3};
use crate::standards::v1::subsets::model::schema::snapshot::{SemioModelSnapshot,SpatialNode,SpatialKind,SemioModelElement,ElementClass,GeometryRef,PropertySet,Property,PsetValue,ModelRelation,RelationKind};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(crate) fn encode(snapshot:&SemioModelSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode(encoding,"semio stdio.semio.model.dsl v1\n","stdio.semio.model.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn point(value:&SemioPoint3,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;for(index,value)in [value.x,value.y,value.z].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}writer.number(value,encoding)?;}writer.delimiter(b"]",encoding)}
fn transform(value:&SemioTransform,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;writer.delimiter(b"[",encoding)?;point(&value.translation,writer,encoding)?;writer.delimiter(b",[",encoding)?;for(index,value)in [value.rotation.x,value.rotation.y,value.rotation.z,value.rotation.w].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}writer.number(value,encoding)?;}writer.delimiter(b"],",encoding)?;point(&value.scale,writer,encoding)?;writer.delimiter(b"]",encoding)}
fn optional(value:&Option<String>,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{match value{None=>if encoding==SnapshotEncoding::Binary{writer.byte(0)}else{writer.bytes(b"[0]")},Some(value)=>{if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"[1,")?;}writer.string(value,encoding)?;writer.delimiter(b"]",encoding)}}}
fn spatial(value:&SpatialNode,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;let(binary,text)=match value.kind{SpatialKind::Site=>(0,b'S'),SpatialKind::Building=>(1,b'B'),SpatialKind::Storey=>(2,b'T'),SpatialKind::Space=>(3,b'P')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;writer.delimiter(b",",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;optional(&value.parent_id,writer,encoding)?;writer.delimiter(b",",encoding)?;transform(&value.placement,writer,encoding)?;writer.delimiter(b"]",encoding)}
fn class(value:&ElementClass,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{let(binary,text):(u8,&[u8])=match value{ElementClass::Wall=>(0,b"WA"),ElementClass::Slab=>(1,b"SL"),ElementClass::Column=>(2,b"CO"),ElementClass::Beam=>(3,b"BE"),ElementClass::Door=>(4,b"DO"),ElementClass::Window=>(5,b"WI"),ElementClass::Roof=>(6,b"RO"),ElementClass::Stair=>(7,b"ST"),ElementClass::Furniture=>(8,b"FU"),ElementClass::Other{..}=>(9,b"OT")};if encoding==SnapshotEncoding::Binary{writer.byte(binary)?}else{writer.bytes(text)?}if let ElementClass::Other{name}=value{writer.delimiter(b"[",encoding)?;writer.string(name,encoding)?;writer.delimiter(b"]",encoding)?;}Ok(())}
fn geometry(value:&GeometryRef,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{let(binary,text)=match value{GeometryRef::None=>(0,b'N'),GeometryRef::Brep{..}=>(1,b'B'),GeometryRef::Mesh{..}=>(2,b'M')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;let id=match value{GeometryRef::None=>return Ok(()),GeometryRef::Brep{brep_id}=>brep_id,GeometryRef::Mesh{mesh_id}=>mesh_id};writer.delimiter(b"[",encoding)?;writer.string(id,encoding)?;writer.delimiter(b"]",encoding)}
fn property(value:&Property,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.key,encoding)?;writer.delimiter(b",",encoding)?;let(binary,text)=match value.value{PsetValue::Text{..}=>(0,b'T'),PsetValue::Number{..}=>(1,b'N'),PsetValue::Boolean{..}=>(2,b'B')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;writer.delimiter(b"[",encoding)?;match &value.value{PsetValue::Text{value}=>writer.string(value,encoding)?,PsetValue::Number{value}=>writer.number(*value,encoding)?,PsetValue::Boolean{value}=>writer.byte(if encoding==SnapshotEncoding::Binary{u8::from(*value)}else{if *value{b'1'}else{b'0'}})?}writer.delimiter(b"]]",encoding)}
fn pset(value:&PropertySet,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.properties,encoding,|writer,value|property(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
fn element(value:&SemioModelElement,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;class(&value.class,writer,encoding)?;writer.delimiter(b",",encoding)?;transform(&value.placement,writer,encoding)?;writer.delimiter(b",",encoding)?;geometry(&value.geometry,writer,encoding)?;writer.delimiter(b",",encoding)?;optional(&value.spatial_id,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.psets,encoding,|writer,value|pset(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
fn relation(value:&ModelRelation,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;let(binary,text):(u8,&[u8])=match value.kind{RelationKind::Aggregates=>(0,b"AG"),RelationKind::ContainedIn=>(1,b"CI"),RelationKind::ConnectsTo=>(2,b"CN"),RelationKind::FillsVoid=>(3,b"FV"),RelationKind::VoidsElement=>(4,b"VE"),RelationKind::Other{..}=>(5,b"OT")};if encoding==SnapshotEncoding::Binary{writer.byte(binary)?;}else{writer.bytes(text)?;}if let RelationKind::Other{label}=&value.kind{writer.delimiter(b"[",encoding)?;writer.string(label,encoding)?;writer.delimiter(b"]",encoding)?;}writer.delimiter(b",",encoding)?;writer.string(&value.from,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.to,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioModelSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nspatial=",encoding)?;writer.list(&snapshot.spatial,encoding,|writer,value|spatial(value,writer,encoding))?;writer.delimiter(b"\nelements=",encoding)?;writer.list(&snapshot.elements,encoding,|writer,value|element(value,writer,encoding))?;writer.delimiter(b"\nrelations=",encoding)?;writer.list(&snapshot.relations,encoding,|writer,value|relation(value,writer,encoding))}
